from __future__ import annotations

from typing import TYPE_CHECKING

import pytest

if TYPE_CHECKING:
    from tests.services.ui.e2e.conftest import App

# this machine's own page: a Browser test loads it, so no outside site is asked
LOCAL_PAGE = "http://127.0.0.1:8000/ping"


@pytest.mark.smoke
def test_a_tool_widget_has_the_three_regions_and_a_bar_of_only_its_five_things(app: App) -> None:
    app.slash("/vods")
    vods = app.widget("chat:r1")
    assert app.regions(vods) == ["viewer-bar", "tool-form", "widget-display", "widget-line"]
    assert app.bar(vods) == ["name", "space", "ai", "inputs", "float", "close"]
    assert vods.locator(".out-kind").inner_text() == "VODs"
    assert app.line(vods) == []  # nothing to say before its first run: the line is there, empty


@pytest.mark.smoke
def test_the_ask_ai_box_opens_in_the_bar_and_the_inputs_dont_move(app: App) -> None:
    app.slash("/vods")
    vods = app.widget("chat:r1")
    form = vods.locator(".tool-form")
    before = form.bounding_box()
    vods.locator("[data-ai-toggle]").click()
    box = vods.locator("[data-ask-box] input")
    box.wait_for(state="visible")
    assert app.bar(vods) == ["name", "ask box", "ai", "inputs", "float", "close"]
    assert form.bounding_box() == before  # "Toggles don't move the content"
    assert box.evaluate("input => document.activeElement === input")
    # outside the form, but sent with it: Enter here asks the AI with the inputs on screen
    box.fill("mkleo vs sparg0")
    sent = box.evaluate("input => Object.fromEntries(new FormData(input.form).entries())")
    assert sent["__ask"] == "mkleo vs sparg0"
    assert "player_1" in sent
    app.page.keyboard.press("Escape")
    box.wait_for(state="detached")
    assert form.bounding_box() == before


def test_a_table_keeps_its_controls_and_the_places_link_in_its_bottom_line(app: App) -> None:
    app.show("chat", "python")
    app.run_cell('import polars as pl; pl.DataFrame({"char": ["mac", "fox", "roy"], "wins": [3, 5, 2]})')
    table = app.widget("cell:c1")
    assert app.regions(table) == ["viewer-bar", "widget-display", "widget-line"]  # no parameters: no Inputs
    assert app.bar(table) == ["name", "space", "float", "close"]
    assert table.locator(".out-kind").inner_text() == "DataFrame"
    # its status is the table's shape, written with a real multiplication sign
    assert app.line(table) == ["3 × 2", "SQL ▸", "Filter rows…", "↗ tab"]  # noqa: RUF001  # the app's text


def test_a_smashdb_console_has_its_ai_in_the_bar_and_the_querys_buttons_by_run(app: App) -> None:
    app.slash("/smashdb")
    console = app.widget("chat:r1")
    assert app.regions(console) == ["viewer-bar", "widget-display", "widget-line"]
    assert app.bar(console) == ["name", "space", "ai", "float", "close"]
    buttons = console.locator(".db-run button").all_inner_texts()
    assert [text.strip() for text in buttons] == ["Run", "History ▸", "Assign ▸"]
    assert app.line(console)[-2:] == ["SQL ▸", "Filter rows…"]


def test_the_browsers_address_is_its_inputs_open_while_blank_folded_once_loaded(app: App) -> None:
    app.slash("/browser")
    browser = app.widget("chat:r1")
    assert app.regions(browser) == ["viewer-bar", "tool-form", "widget-display", "widget-line"]
    assert app.bar(browser) == ["name", "space", "inputs", "float", "close"]
    assert browser.locator(".out-kind").inner_text() == "Browser"
    address = browser.locator('input[name="url"]')
    address.fill(LOCAL_PAGE)
    address.press("Enter")
    browser.locator(".tool-form").wait_for(state="detached")  # folded: the page gets the room
    assert app.regions(browser) == ["viewer-bar", "widget-display", "widget-line"]
    assert browser.locator("iframe.player-frame").get_attribute("src") == LOCAL_PAGE
    assert app.line(browser) == ["127.0.0.1:8000", "Alt+← Back · Alt+→ Forward", "Open ↗"]
    browser.locator(".form-toggle").click()  # Inputs: the address again
    assert address.input_value() == LOCAL_PAGE


def test_every_widget_added_by_hand_has_the_same_bar_shape(app: App) -> None:
    # the bar is the frame's: whatever the widget, it starts with its name, ends float, close
    for number, command in enumerate(["/vods", "/usage", "/smashdb", "/browser", "/config"], start=1):
        app.slash(command)
        bar = app.bar(app.widget(f"chat:r{number}"))
        assert bar[0] == "name", command
        assert bar[-2:] == ["float", "close"], command
        assert set(bar) <= {"name", "space", "ai", "inputs", "float", "close"}, command
